        for(String key:List.of("basic","evolved","energy","wrong","special","trainer","tool")){boolean mon=key.equals("basic")||key.equals("evolved"),en=Set.of("energy","wrong","special").contains(key);defs.add(new CardDefinition(key,key,mon?CardCategory.POKEMON:en?CardCategory.ENERGY:CardCategory.TRAINER,key.equals("trainer")?TrainerCategory.SUPPORTER:key.equals("tool")?TrainerCategory.TOOL:TrainerCategory.NONE,"H",Set.of("international"),key.equals("basic"),key.equals("energy")||key.equals("wrong"),60,Map.of(),EffectSupport.SUPPORTED,null));if(mon)pokemon.put(key,new PokemonProfile(500,1,key.equals("evolved")?"basic":null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(300,false)),List.of(),key.equals("basic")?EnergyType.DRAGON:EnergyType.GRASS));}
